class Solution {
    public int numRollsToTarget(int n,int k,int target){
        final int MOD=1000000007;
        long[] dp=new long[target+1];
        dp[0]=1;
        for(int dice=0;dice<n;dice++){
            long[] next=new long[target+1];
            for(int sum=1;sum<=target;sum++)for(int face=1;face<=k&&face<=sum;face++)next[sum]=(next[sum]+dp[sum-face])%MOD;
            dp=next;
        }
        return (int)dp[target];
    }
}

code.kotlin:
class Solution {
    fun numRollsToTarget(n:Int,k:Int,target:Int):Int{
        val mod=1000000007L;
        var dp=LongArray(target+1);
        dp[0]=1;
        repeat(n){
            val next=LongArray(target+1);
            for(sum in 1..target)for(face in 1..minOf(k,sum))next[sum]=(next[sum]+dp[sum-face])%mod;
            dp=next
        };
        return dp[target].toInt()
    }
}

code.cpp:
class Solution {
    public: int numRollsToTarget(int n,int k,int target){
        const int MOD=1000000007;
        vector<long long> dp(target+1);
        dp[0]=1;
        while(n--){
            vector<long long> next(target+1);
            for(int sum=1;sum<=target;++sum)for(int face=1;face<=k&&face<=sum;++face)next[sum]=(next[sum]+dp[sum-face])%MOD;
            dp.swap(next);
        }
        return dp[target];
    }
};
